package com.wissenup.domain.fee.repository;import com.wissenup.domain.fee.entity.StudentFee;import jakarta.persistence.LockModeType;import org.springframework.data.jpa.repository.*;import java.util.*;public interface StudentFeeRepository extends JpaRepository<StudentFee,Long>{List<StudentFee>findAllByOrganizationIdAndStudentIdOrderByDueDateAsc(Long org,Long student);List<StudentFee>findAllByOrganizationIdAndStatusIgnoreCaseOrderByDueDateAsc(Long org,String status);Optional<StudentFee>findByOrganizationIdAndStudentIdAndFeeStructureId(Long org,Long student,Long structure);@Lock(LockModeType.PESSIMISTIC_WRITE)@Query("select f from StudentFee f where f.studentFeeId=:id and f.organizationId=:org")Optional<StudentFee>lockByIdAndOrganizationId(Long id,Long org);}
